from pathlib import Path
import time,subprocess,datetime
p=Path('.git/index.lock');a=p.stat();print('lock age seconds',round(time.time()-a.st_mtime),'created/modified',datetime.datetime.fromtimestamp(a.st_mtime,datetime.timezone.utc).isoformat())
print('active git executables', [line for line in subprocess.check_output(['ps','-axo','pid,comm'],text=True).splitlines() if line.strip().endswith('/git')])
time.sleep(2)
b=p.stat()
if (a.st_ino,a.st_mtime_ns,a.st_size)!=(b.st_ino,b.st_mtime_ns,b.st_size):raise RuntimeError('Lock changed; not removing')
if time.time()-b.st_mtime<120:raise RuntimeError('Recent lock; not removing')
if any(line.strip().endswith('/git') for line in subprocess.check_output(['ps','-axo','pid,comm'],text=True).splitlines()):raise RuntimeError('Active Git process; not removing')
if subprocess.run(['lsof',str(p)],capture_output=True).stdout:raise RuntimeError('Open lock; not removing')
p.unlink();print('Removed unchanged abandoned empty Git lock; no active Git writer or open holder.')
